const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Look up user by email
const user = db.prepare(\"SELECT * FROM users WHERE json_extract(data, '$.email') = ?\").get('evan.parker@email.com');
if (!user) {
  // Try alternate approach
  const allUsers = db.prepare('SELECT * FROM users').all();
  console.log('All user count:', allUsers.length);
  const match = allUsers.find(u => {
    const d = JSON.parse(u.data || '{}');
    return d.email === 'evan.parker@email.com';
  });
  if (match) console.log('Found user:', JSON.stringify(JSON.parse(match.data), null, 2));
  else {
    console.log('No user found with that email.');
    // Show schema
    const cols = db.prepare('PRAGMA table_info(users)').all();
    console.log('users columns:', cols.map(c => c.name));
    console.log('Sample:', allUsers.slice(0,2).map(u => Object.keys(u)));
  }
} else {
  console.log(JSON.stringify(JSON.parse(user.data), null, 2));
}
"

